<script>
import { onMount } from 'svelte';import {ArrowLeft,BookOpen,Search} from 'lucide-svelte';let data=null,query='';onMount(async()=>{const r=await fetch('/data/knowledge-base.json');data=await r.json();});$: records=data?.topicRecords||[];$: shown=records.filter(x=>(x.title||'').includes(query)||(x.field||'').includes(query));
